#include <stdio.h>
#include <stdbool.h>
#include <string.h>

void contadorDePalavras(void) {
    char frase[100] = "";
    scanf("%99[^\n]", frase);
    int palavras = 0;

    bool dentroDePalavra = false;
    int n = strlen(frase);
    for (int i = 0; i < n; i++) {
        if (frase[i] == ' ') {
            dentroDePalavra = false;
        } else if (!dentroDePalavra) {
            dentroDePalavra = true;
            palavras++;
        }
    }
    printf("%d\n", palavras);
}
